        if (extraHeaders is not null)
        {
            foreach (var (key, value) in extraHeaders)
            {
                context.Request.Headers[key] = value;
            }
        }

        if (body is not null)
        {
            var bytes = Encoding.UTF8.GetBytes(body);
            context.Request.Body = new MemoryStream(bytes);
            context.Request.Headers.ContentLength = bytes.Length;
        }

        await handler(context);
        context.Response.Body.Position = 0;
        return (context, vm);
    }

    private static async Task<JsonDocument> ReadJsonAsync(HttpContext context)
    {
        using var reader = new StreamReader(context.Response.Body, Encoding.UTF8, leaveOpen: true);
        var bodyString = await reader.ReadToEndAsync();
        return JsonDocument.Parse(bodyString);
    }

    // ── Bodyless POST (the key behavioural change) ──────────────────────

    /// <summary>
    /// Under Kestrel (RFC 9112), a POST with no Content-Length is a
    /// valid empty-body request — the command MUST execute and return 200.
    /// This is the deliberate semantic change from the old HttpListener
    /// 411 guard.
    /// </summary>
    [AvaloniaFact]
    public async Task BodylessPost_NoContentLength_Returns200_AndExecutesCommand()
    {
        var (context, vm) = await InvokeCommandAsync("pause-toggle");

        Assert.Equal(200, context.Response.StatusCode);

        using var doc = await ReadJsonAsync(context);
        Assert.True(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("pause-toggle", doc.RootElement.GetProperty("command").GetString());

        // Command executed: PauseRequested flipped.
        Assert.True(vm.PauseRequested,
            "A bodyless POST must execute the command. PauseRequested should be true.");
    }

    /// <summary>
    /// A POST with Content-Length: 0 is semantically identical to a
    /// bodyless POST under Kestrel — both are valid empty-body requests.
    /// </summary>
    [AvaloniaFact]
    public async Task ContentLengthZero_Post_Returns200_AndExecutesCommand()
    {
        var (context, vm) = await InvokeCommandAsync(
            "pause-toggle",
            extraHeaders: new Dictionary<string, string> { ["Content-Length"] = "0" });

        Assert.Equal(200, context.Response.StatusCode);

        using var doc = await ReadJsonAsync(context);
        Assert.True(doc.RootElement.GetProperty("ok").GetBoolean());

        Assert.True(vm.PauseRequested,
            "A Content-Length: 0 POST must execute the command. PauseRequested should be true.");
    }

    // ── Disabled command ────────────────────────────────────────────────

    [AvaloniaFact]
    public async Task DisabledCommand_Returns409()
    {
        // run-selected is disabled when no task is selected.
        var (context, _) = await InvokeCommandAsync("run-selected");

        Assert.Equal(409, context.Response.StatusCode);

        using var doc = await ReadJsonAsync(context);
        Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("disabled", doc.RootElement.GetProperty("error").GetString());
    }

    // ── Unknown command ─────────────────────────────────────────────────

    [AvaloniaFact]
    public async Task UnknownCommand_Returns404()
    {
        var (context, _) = await InvokeCommandAsync("nonexistent-command");

        Assert.Equal(404, context.Response.StatusCode);

        using var doc = await ReadJsonAsync(context);
        Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("unknown command", doc.RootElement.GetProperty("error").GetString());
    }

    // ── Confirm-gated command ───────────────────────────────────────────

    [AvaloniaFact]
    public async Task ConfirmGatedCommand_WithoutConfirm_Returns409_AndNoEffect()
    {
        // mark-done requires {"confirm":true} — an empty-body POST
        // does not carry confirm, so the command must be refused.
        var (context, _) = await InvokeCommandAsync("mark-done");

        Assert.Equal(409, context.Response.StatusCode);

        using var doc = await ReadJsonAsync(context);
        Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("confirmation required", doc.RootElement.GetProperty("error").GetString());

        // No task was selected, but more importantly the command was
        // gated BEFORE execution — confirm-gated safety holds.
    }

    // ── Token auth on commands ──────────────────────────────────────────

    [AvaloniaFact]
    public async Task Command_WithToken_Returns401_WithoutHeader()
    {
        var (context, _) = await InvokeCommandAsync("pause-toggle", token: "s3cret");

        Assert.Equal(401, context.Response.StatusCode);

        using var doc = await ReadJsonAsync(context);
        Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("unauthorized", doc.RootElement.GetProperty("error").GetString());
    }

    [AvaloniaFact]
    public async Task Command_WithToken_Returns200_WithCorrectHeader()
    {
        var (context, vm) = await InvokeCommandAsync(
            "pause-toggle", token: "letmein",
            extraHeaders: new Dictionary<string, string> { ["X-VR-Token"] = "letmein" });

        Assert.Equal(200, context.Response.StatusCode);
        Assert.True(vm.PauseRequested);
    }
}

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;

namespace VisualRelay.App.Services;

/// <summary>
/// Embedded localhost HTTP control server. Hosts the control API handler on
/// Kestrel (ASP.NET Core) bound to <c>http://127.0.0.1:&lt;port&gt;/</c>
/// (loopback ONLY — never <c>+</c>/<c>*</c>, so macOS shows no firewall
/// prompt and the surface is not remotely reachable). Kestrel manages its
/// own accept loop internally; ControlApi marshals every VM/window touch
/// onto the UI thread. A startup failure (e.g. port in use) is caught and
/// logged — it never crashes or blocks app startup.
/// </summary>
public sealed partial class ControlServer(ControlApi api, ControlServerOptions options) : IDisposable
{
    private WebApplication? _app;
    private int _boundPort;

    /// <summary>The actual port the server bound (useful when <see cref="ControlServerOptions.Port"/> is 0).</summary>
    public int BoundPort => _boundPort;

    /// <summary>
    /// Starts the server if enabled. Never throws: a bind/start failure is
    /// caught and reported to stderr/Console so app startup always continues.
    /// On success, writes one confirmation line to Console.
    /// </summary>
    public void Start()
    {
        if (!options.Enabled)
        {
            Console.Error.WriteLine("vr-control: disabled via VR_CONTROL_DISABLE");
            return;
        }

        try
        {
            var builder = WebApplication.CreateEmptyBuilder(new WebApplicationOptions());
            builder.Logging.ClearProviders();
            builder.WebHost.UseKestrel();
            builder.WebHost.UseUrls($"http://127.0.0.1:{options.Port}");

            var app = builder.Build();
            app.Run(BuildHandler(api, options));

            // Run StartAsync on the thread pool so Kestrel never synchronises
            // back to the Avalonia UI dispatcher, which would deadlock when
            // the calling thread blocks on GetAwaiter().GetResult().
            Task.Run(() => app.StartAsync()).GetAwaiter().GetResult();

            // Read the actual bound port (surfaces port 0 → OS-assigned port).
            _boundPort = app.Urls
                .Select(u => new Uri(u))
                .Where(u => u.Port > 0)
                .Select(u => u.Port)
                .FirstOrDefault();
            if (_boundPort == 0) _boundPort = options.Port;

            _app = app;

            Console.Error.WriteLine($"vr-control: listening on http://127.0.0.1:{_boundPort}");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"vr-control: failed to start ({ex.Message}); control API disabled");
            _app = null;
        }
    }

    /// <summary>Releases the server (idempotent; delegates to Stop()).</summary>
    public void Dispose() => Stop();

    /// <summary>
    /// Stops the server. Safe to call when not started. Bounded at 5 s by
    /// a CancellationToken; any exception is swallowed — best-effort
    /// teardown must never throw. The stop runs on the thread pool to avoid
    /// synchronising back to the Avalonia dispatcher and deadlocking.
    /// </summary>
    public void Stop()
    {
        var app = _app;
        _app = null;

        if (app is null) return;

        // Run the entire async stop sequence on the thread pool. If StopAsync
        // ignores the 5 s cancellation, the pool thread is abandoned but the
        // caller does not hang.
        Task.Run(async () =>
        {
            try
            {
                using var stopCts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
                await app.StopAsync(stopCts.Token);
            }
            catch
            {
                // Best-effort shutdown.
            }
            finally
            {
                try { (app as IDisposable)?.Dispose(); }
                catch { /* Best-effort cleanup; nothing to do. */ }
            }
        }).GetAwaiter().GetResult();
    }
}

